let rec factorial n =
  if n <= 1 then 1 else n * factorial (n - 1)

let () =
  Printf.printf "%d\n" (factorial 5)

let rec sum list =
  match list with
  | [] -> 0
  | head :: tail -> head + sum tail

let () =
  Printf.printf "%d\n" (sum [3; 5; 7])

let rec double_all list =
  match list with
  | [] -> []
  | x :: rest -> (x * 2) :: double_all rest

let () =
  print_endline (String.concat " " (List.map string_of_int (double_all [1; 2; 3])))

let sum list =
  let rec go acc rest =
    match rest with
    | [] -> acc
    | x :: tail -> go (acc + x) tail
  in
  go 0 list

let () =
  Printf.printf "%d\n" (sum [10; 20; 30])

